  wwl_t t19 = wwl_add( t15, t18 );  /* < 2^55 */
  wwl_t t20 = wwl_shl( t19, 1 );  /* < 2^56 */
  wwl_t t21 = wwl_madd52lo( t20, a->limb[2], a->limb[2] );  /* < 2^56 */
  wwl_t t22 = wwl_madd52hi( z2, a->limb[4], a->limb[4] );  /* < 2^52 */
